<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getMovements, type Movement } from "../../api"; const route = useRoute(); const movements = ref<Movement[]>([]); onMounted(async () => { movements.value = await getMovements(String(route.params.id)); });</script><template><section class="detail-tab"><h2>Movimientos</h2><ul class="customer-repair-items"><li v-for="movement in movements" :key="movement.id"><strong>{{ movement.quantity > 0 ? '+' : '' }}{{ movement.quantity }}</strong><span>{{ movement.type }} - {{ movement.note || "Sin nota" }}</span><em>{{ new Date(movement.createdAt).toLocaleString("es-ES") }}</em></li></ul><p v-if="!movements.length" class="empty">No hay movimientos registrados.</p></section></template>